export interface SemaforoFijo {
  semaforoId: string;
  lng: number;
  lat: number;
  zona: string;
}

/**
 * Dataset fijo de semáforos reales (`highway=traffic_signals`) para Lima Metropolitana completa
 * (46 distritos) — ticket #9 originalmente cubría solo San Borja y sus 5 distritos colindantes más
 * Jesús María (962 semáforos); ampliado a pedido explícito del usuario tras descargar el extracto
 * completo de Overpass para toda Lima (`docs/semaforos-osm.json`), evaluando la alternativa de
 * consultar Overpass en runtime y descartándola: Overpass tiene rate limits/timeouts agresivos
 * para un dato que no cambia, así que un reemplazo estático más grande es preferible a una
 * dependencia de red en cada carga. `semaforoId` es el id real del nodo OSM (`docs/semaforos-osm.json`
 * lo trae con un prefijo `osm-` que se quitó al generar este archivo, para mantener el mismo
 * formato — id numérico crudo como string — que ya esperaba el resto del código, p.ej. el hash de
 * offset determinístico en `fase.ts`). `zona` es el distrito de origen de la consulta (no un rótulo
 * de calle). Los campos `nombre`/`avenida`/`estado` del JSON fuente no se incluyen: son uniformes
 * en las 3784 filas ("Semáforo", "Sin datos de vía (OpenStreetMap)", "activo") y no aportan
 * información real. Seedeado como datos estáticos: no se vuelve a consultar Overpass en runtime.
 * 3784 semáforos.
 */
